                "Crie a classe Produto com construtor promovido de duas propriedades públicas: $nome (string) e $preco (float), com o corpo do construtor vazio.",
                U(new[] {
                    PhpMix("class Produto {\n    public function __construct(\n        public @1string $nome,\n        public @1float $preco@0\n    ) {}\n}", new[] { "", "," }, new[] { "", "readonly " }),
                    PhpMix("class Produto {\n    public function __construct(public @0string $nome, public @0float $preco) {}\n}", new[] { "", "readonly " }) }),
                A("Construtor promovido: a visibilidade vai no próprio parâmetro, e a propriedade é criada sozinha.", "class Produto {\n    public function __construct(public string $nome, public float $preco) {}\n}"),
                A("class Produto", "Declara a classe.", "__construct", "Construtor: roda no new.", "public string $nome", "Parâmetro promovido: cria e preenche a propriedade.", "{}", "Corpo vazio: a promoção já atribuiu tudo."),
                "Antes do PHP 8 era preciso declarar as propriedades e atribuir uma a uma no construtor ($this->nome = $nome;)."));
            list.Add(C(H, 1, "code", "Criando o objeto",
                "Com a classe Produto pronta (construtor: nome e preço), é hora de cadastrar o Latte.",
                "Em duas linhas: crie em $latte um Produto com nome \"Latte\" e preço 12.5; depois mostre com echo a propriedade nome de $latte.",
                PhpMix("$latte = new Produto(@0);\necho $latte->nome;", new[] { "\"Latte\", 12.5", "\"Latte\", 12.50", "nome: \"Latte\", preco: 12.5" }),
                A("Objetos são criados com new. Propriedades são acessadas com -> (não com ponto, que concatena).", "$latte = new Produto(\"Latte\", 12.5);\necho $latte->...;"),
                A("new Produto(\"Latte\", 12.5)", "Cria o objeto chamando o construtor.", "$latte->nome", "Lê a propriedade nome do objeto."),
                "Argumentos nomeados (PHP 8) deixam a chamada mais clara: new Produto(nome: \"Latte\", preco: 12.5)."));
            list.Add(C(H, 1, "code", "ID pela URL",
                "Em /pedido.php?id=12abc, o código usava $_GET[\"id\"] direto. A Fê quer ler e validar como inteiro numa chamada só.",
                "Guarde em $id o parâmetro id da query string (GET) validado como inteiro, usando filter_input.",
                A("$id = filter_input(INPUT_GET, \"id\", FILTER_VALIDATE_INT);"),
                A("filter_input recebe: a origem (INPUT_GET, INPUT_POST...), o nome do campo e o filtro.", "$id = filter_input(INPUT_GET, \"id\", FILTER_VALIDATE_____);"),
                A("INPUT_GET", "Lê da query string, sem tocar em $_GET.", "\"id\"", "Nome do parâmetro.", "FILTER_VALIDATE_INT", "Devolve int, ou false se não for inteiro."),
                "filter_input devolve null se o parâmetro não veio e false se veio inválido — trate os dois (ex.: responda 400)."));
            list.Add(C(H, 1, "cmd", "Migration de avaliações",
                "Os clientes vão poder avaliar produtos. O Rui pediu a migration da tabela avaliacoes.",
                "Gere com o artisan a migration create_avaliacoes_table (sem opções).",
                A("php artisan make:migration create_avaliacoes_table"),
                A("Igual ao make:controller, mas o gerador é de migration.", "php artisan make:_________ create_avaliacoes_table"),
                A("make:migration", "Gera o arquivo em database/migrations com data e hora no nome.", "create_avaliacoes_table", "Pelo padrão create_..._table o Laravel já prepara o Schema::create(\"avaliacoes\")."),
                "Depois de editar as colunas da migration, rode php artisan migrate."));
            list.Add(C(H, 1, "code", "Preço com taxa",
                "A classe Produto (com a propriedade $preco) precisa calcular o preço com os 10% de serviço.",
                "Escreva o método público comTaxa, sem parâmetros e com retorno float, que retorna a propriedade preco multiplicada por 1.1 (em uma linha).",
                PhpMix("public function comTaxa(): float { return @0; }", new[] { "$this->preco * 1.1", "1.1 * $this->preco", "$this->preco * 1.10" }),
                A("Dentro da classe, o próprio objeto é $this. Propriedades: $this->nome.", "public function comTaxa(): float { return $this->preco * ...; }"),
                A("public function comTaxa(): float", "Método público com retorno float.", "$this->preco", "A propriedade preco DESTE objeto."),
                "$preco sozinho, dentro do método, seria uma variável local inexistente: propriedades sempre com $this->."));
            list.Add(C(H, 1, "code", "E-mail interno",
                "Funcionários têm desconto e o e-mail deles termina em @micorosoft.com — mas tem gente que digita @Micorosoft.COM.",
                "Guarde em $interno o resultado de str_ends_with aplicado a $email convertido para minúsculas (strtolower), procurando \"@micorosoft.com\".",
                A("$interno = str_ends_with(strtolower($email), \"@micorosoft.com\");", "$interno = str_ends_with(mb_strtolower($email), \"@micorosoft.com\");"),
                A("Converta primeiro, depois teste: uma função dentro da outra.", "$interno = str_ends_with(strtolower($email), \"...\");"),
                A("strtolower($email)", "Padroniza em minúsculas.", "str_ends_with(texto, fim)", "true se o texto termina com o trecho informado."),
                "str_contains, str_starts_with e str_ends_with chegaram no PHP 8; antes era preciso strpos/substr."));
            list.Add(C(H, 1, "code", "Quantidade inválida",
                "Alguém mandou um pedido com quantidade -3 e o estoque AUMENTOU. A função adicionarItem precisa recusar isso.",
                "Escreva um if que, quando $quantidade for menor ou igual a 0, lance uma InvalidArgumentException com a mensagem \"Quantidade inválida\".",
                PhpMix("if (@0) {\n    throw new @1InvalidArgumentException(\"Quantidade @2\");\n}",
                    new[] { "$quantidade <= 0", "$quantidade < 1", "0 >= $quantidade" }, new[] { "", "\\" }, new[] { "inválida", "invalida" }),
                A("Exceções são lançadas com throw new NomeDaExcecao(\"mensagem\").", "if ($quantidade <= 0) {\n    throw new InvalidArgumentException(\"...\");\n}"),
                A("$quantidade <= 0", "Condição de erro.", "throw", "Interrompe a função e lança a exceção.", "InvalidArgumentException", "Exceção nativa para argumentos inválidos."),
                "Falhar cedo (validar no começo da função) evita deixar dados inconsistentes."));
            list.Add(C(H, 1, "code", "Capturando o erro",
                "buscarPedido($id) lança PedidoNaoEncontradoException quando o id não existe, e a página está mostrando um erro fatal feio.",
                "Chame buscarPedido($id) guardando o resultado em $pedido dentro de um try; capture PedidoNaoEncontradoException como $e e mostre com echo a mensagem da exceção.",
                A("try {\n    $pedido = buscarPedido($id);\n} catch (PedidoNaoEncontradoException $e) {\n    echo $e->getMessage();\n}"),
                A("try { ... } catch (TipoDaExcecao $e) { ... }. A mensagem vem do método getMessage().", "try {\n    $pedido = buscarPedido($id);\n} catch (PedidoNaoEncontradoException $e) {\n    echo $e->...;\n}"),
                A("try", "Bloco que pode lançar exceção.", "catch (PedidoNaoEncontradoException $e)", "Só captura esse tipo de exceção.", "$e->getMessage()", "Texto passado no throw."),
                "Capture a exceção mais específica possível. Um catch (Exception $e) genérico esconde bugs que você não previu."));
            list.Add(C(H, 1, "cmd", "PHPUnit no projeto",
                "Hora de escrever testes. O PHPUnit só é necessário em desenvolvimento, nunca no servidor de produção.",
                "Adicione o pacote phpunit/phpunit como dependência de desenvolvimento com o Composer.",
                A("composer require --dev phpunit/phpunit", "composer require phpunit/phpunit --dev"),
                A("É o mesmo require de sempre, com uma opção que marca o pacote como \"de desenvolvimento\".", "composer require --___ phpunit/phpunit"),
                A("composer require", "Adiciona o pacote.", "--dev", "Grava em require-dev no composer.json."),
                "composer install --no-dev ignora tudo o que está em require-dev."));
            list.Add(C(H, 1, "code", "Contador de visitas",
                "O Igor quer saber quantas páginas cada visitante abriu, guardando a contagem na sessão.",
                "Em duas linhas: inicie a sessão; depois guarde em $_SESSION[\"visitas\"] o valor atual dela mais 1, usando ?? 0 para o primeiro acesso (atenção aos parênteses).",
                A("session_start();\n$_SESSION[\"visitas\"] = ($_SESSION[\"visitas\"] ?? 0) + 1;",
                  "session_start();\n$_SESSION[\"visitas\"] = 1 + ($_SESSION[\"visitas\"] ?? 0);"),
                A("Primeiro session_start(). Depois: valor atual (ou 0) + 1. O ?? tem precedência MENOR que o +.", "session_start();\n$_SESSION[\"visitas\"] = ($_SESSION[\"visitas\"] ?? 0) + 1;"),
                A("session_start()", "Abre (ou retoma) a sessão do visitante.", "($_SESSION[\"visitas\"] ?? 0)", "0 no primeiro acesso.", "+ 1", "Soma a visita atual."),
                "Sem os parênteses, $x ?? 0 + 1 vira $x ?? (0 + 1): depois do primeiro acesso o contador nunca mais sobe."));
            list.Add(C(H, 1, "code", "Sair do sistema",
                "O botão Sair só redirecionava — a sessão continuava viva no servidor. A sessão já foi iniciada neste arquivo.",
                "Em duas linhas: esvazie os dados da sessão atribuindo um array vazio a $_SESSION e depois destrua a sessão.",
                A("$_SESSION = [];\nsession_destroy();", "$_SESSION = array();\nsession_destroy();"),
                A("Limpe o array e depois chame a função que destrói a sessão no servidor.", "$_SESSION = [];\nsession_______();"),
                A("$_SESSION = []", "Apaga os dados já carregados nesta requisição.", "session_destroy()", "Remove a sessão guardada no servidor."),
                "Para um logout completo, apague também o cookie: setcookie(session_name(), \"\", time() - 3600, \"/\")."));
            list.Add(C(H, 1, "code", "Interface de pagamento",
                "O caixa aceita Pix e cartão. O Igor quer um contrato comum: toda forma de pagamento precisa ter o método pagar.",
                "Declare a interface Pagamento com o método público pagar, que recebe $valor do tipo float e retorna bool.",
                A("interface Pagamento {\n    public function pagar(float $valor): bool;\n}"),
                A("Na interface os métodos não têm corpo: a assinatura termina com ponto e vírgula.", "interface Pagamento {\n    public function pagar(float $valor): ____;\n}"),
                A("interface Pagamento", "Contrato: lista métodos sem implementação.", "public function pagar(float $valor): bool;", "Assinatura que toda classe que implementar Pagamento precisa ter."),
                "Depois: class Pix implements Pagamento { ... }. Quem usa depende da interface, não da classe concreta."));
            list.Add(C(H, 1, "code", "Ordenando por preço",
                "O cardápio do app deve aparecer do mais barato para o mais caro. $produtos é uma lista de arrays com as chaves nome e preco.",
                "Ordene $produtos pelo preço em ordem crescente com usort e uma arrow function de parâmetros $a e $b que use o operador nave espacial (<=>).",
                A("usort($produtos, fn($a, $b) => $a[\"preco\"] <=> $b[\"preco\"]);",
                  "usort($produtos, function ($a, $b) { return $a[\"preco\"] <=> $b[\"preco\"]; });"),
                A("usort(array, função). A função compara dois itens; <=> devolve -1, 0 ou 1.", "usort($produtos, fn($a, $b) => $a[\"preco\"] <=> ...);"),
                A("usort", "Ordena com uma função de comparação sua.", "$a[\"preco\"] <=> $b[\"preco\"]", "Negativo: $a vem antes; positivo: $b vem antes."),
                "usort altera o próprio array e devolve true — não faça $x = usort(...). Troque $a e $b de lugar para ordem decrescente."));
            list.Add(C(H, 1, "code", "Namespace do serviço",
                "O arquivo app/Services/CheckoutService.php vai usar o model Pedido. Sem namespace, classes de mesmo nome colidem.",
                "Escreva as duas primeiras linhas do arquivo: declare o namespace App\\Services e importe a classe App\\Models\\Pedido com use.",
                A("namespace App\\Services;\n\nuse App\\Models\\Pedido;"),
                A("namespace declara onde a classe deste arquivo mora; use importa outra classe. O separador é a barra invertida.", "namespace App\\Services;\nuse App\\Models\\...;"),
                A("namespace App\\Services;", "As classes deste arquivo ficam em App\\Services.", "use App\\Models\\Pedido;", "Agora dá para escrever só Pedido no código."),
                "Pelo PSR-4 do Composer, App\\Services\\CheckoutService fica em app/Services/CheckoutService.php: namespace e pasta andam juntos."));
            list.Add(C(H, 1, "code", "JSON legível",
                "O JSON de debug do cardápio vem numa linha só e com \\u00e3 no lugar de ã. A Fê quer conseguir ler.",
                "Mostre com echo $cardapio em JSON com indentação e sem escapar caracteres Unicode, combinando as duas flags com |.",
                A("echo json_encode($cardapio, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);",
                  "echo json_encode($cardapio, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);"),
                A("json_encode aceita um segundo argumento com flags JSON_... (pretty = bonito; unescaped unicode = acentos como estão).", "echo json_encode($cardapio, JSON_PRETTY_PRINT | JSON_________);"),
                A("JSON_PRETTY_PRINT", "Quebra linhas e indenta.", "JSON_UNESCAPED_UNICODE", "Mantém ã, é, ç em vez de \\u00e3.", "|", "Combina flags (OU bit a bit)."),
                "Em produção, o JSON compacto economiza bytes. JSON_UNESCAPED_SLASHES evita \\/ em URLs."));
            list.Add(C(H, 1, "code", "Cliente por e-mail",
                "Tela de recuperação de senha: buscar o cliente pelo e-mail digitado, que está em $email. Só pode haver um.",
                "Em três linhas: prepare em $stmt (com $pdo) a consulta SELECT * FROM clientes WHERE email = ?; execute com $email num array; guarde em $cliente uma única linha com fetch.",
                PhpMix("$stmt = $pdo->prepare(\"SELECT * FROM clientes WHERE email = ?\");\n$stmt->execute(@0);\n$cliente = $stmt->fetch(@1);",
                    new[] { "[$email]", "array($email)" }, new[] { "", "PDO::FETCH_ASSOC", "\\PDO::FETCH_ASSOC" }),
                A("prepare → execute → fetch. fetch() traz UMA linha (fetchAll traria todas).", "$stmt = $pdo->prepare(\"... WHERE email = ?\");\n$stmt->execute([$email]);\n$cliente = $stmt->fetch();"),
                A("WHERE email = ?", "Marcador: o e-mail vai separado do SQL.", "execute([$email])", "Envia o valor com segurança.", "fetch()", "Uma linha, ou false se não achou."),
                "fetch() devolve false quando não acha nada: confira com if (!$cliente) antes de usar."));
            list.Add(C(H, 1, "code", "Total de pedidos",
                "O painel mostra quantos pedidos existem. A consulta é fixa: não tem nenhum dado vindo do usuário.",
                "Execute com $pdo->query a consulta SELECT COUNT(*) FROM pedidos e guarde em $qtd o valor da primeira coluna com fetchColumn (pode encadear numa linha).",
                A("$qtd = $pdo->query(\"SELECT COUNT(*) FROM pedidos\")->fetchColumn();",
                  "$stmt = $pdo->query(\"SELECT COUNT(*) FROM pedidos\");\n$qtd = $stmt->fetchColumn();"),
                A("query() executa SQL fixo e já devolve o resultado; fetchColumn() pega o valor da 1ª coluna.", "$qtd = $pdo->query(\"SELECT COUNT(*) FROM pedidos\")->fetch______();"),
                A("$pdo->query(...)", "Executa direto (sem prepare): só para SQL fixo.", "->fetchColumn()", "Devolve só o número, sem array."),
                "Com QUALQUER dado externo na consulta, use prepare + execute em vez de query."));
            list.Add(C(H, 1, "code", "Página Sobre",
                "A página Sobre do Café 365 é só uma view estática, sem controller.",
                "Em routes/web.php, registre a rota GET /sobre com uma função anônima que retorna a view \"sobre\".",
                U(new[] {
                    PhpMix("Route::get(\"@0\", function () {\n    return view(\"sobre\");\n});", new[] { "/sobre", "sobre" }),
                    PhpMix("Route::get(\"@0\", fn () => view(\"sobre\"));", new[] { "/sobre", "sobre" }),
                    PhpMix("Route::get(\"@0\", fn() => view(\"sobre\"));", new[] { "/sobre", "sobre" }) }),
                A("Route::get(caminho, ação). A ação pode ser uma função que retorna view(\"nome\").", "Route::get(\"/sobre\", function () {\n    return view(\"...\");\n});"),
                A("Route::get(\"/sobre\", ...)", "Responde a GET /sobre.", "function () { ... }", "Função anônima (closure) como ação.", "view(\"sobre\")", "Renderiza resources/views/sobre.blade.php."),
                "Para views estáticas existe o atalho Route::view(\"/sobre\", \"sobre\")."));
            list.Add(C(H, 1, "code", "Eloquent: where e first",
                "No backend Laravel, o login precisa achar o cliente pelo e-mail. O model Cliente já existe.",
                "Guarde em $cliente o primeiro Cliente cuja coluna email seja igual a $email, usando where e first do Eloquent.",
                A("$cliente = Cliente::where(\"email\", $email)->first();", "$cliente = Cliente::where(\"email\", \"=\", $email)->first();"),
                A("Consultas Eloquent começam no model (Model::where) e terminam com first(), get()...", "$cliente = Cliente::where(\"email\", $email)->_____();"),
                A("Cliente::where(\"email\", $email)", "WHERE email = ? (com prepared statement por baixo).", "->first()", "Primeiro resultado (model) ou null."),
                "first() devolve um model ou null; get() devolve uma Collection (mesmo com um item só)."));

            // ════════════════════════ PROFISSIONAL ════════════════════════
            list.Add(C(H, 2, "code", "Busca com LIKE",
                "A busca de produtos fazia \"... LIKE '%$busca%'\" — SQL Injection garantido. Ao trocar por ?, a Fê escreveu LIKE '%?%' e nada funcionou: entre aspas, o ? vira texto.",
                "Em duas linhas: prepare em $stmt (com $pdo) a consulta SELECT * FROM produtos WHERE nome LIKE ? e execute passando num array o valor de $busca com % antes e depois.",
                PhpMix("$stmt = $pdo->prepare(\"SELECT * FROM produtos WHERE nome LIKE ?\");\n$stmt->execute(@0);",
                    new[] { "[@1]", "array(@1)" }, new[] { "\"%\" . $busca . \"%\"", "\"%$busca%\"", "\"%{$busca}%\"" }),
                A("Os curingas % vão no VALOR, não no SQL. O marcador ? fica sozinho, sem aspas.", "$stmt->execute([\"%\" . $busca . \"%\"]);"),
                A("LIKE ?", "Marcador sem aspas: o PDO cuida do valor.", "\"%\" . $busca . \"%\"", "Monta o padrão %texto% fora do SQL."),
                "Se % e _ digitados pelo usuário não devem virar curingas, escape-os antes com addcslashes($busca, \"%_\")."));
            list.Add(C(H, 2, "code", "Conexão robusta",
                "A conexão antiga não definia o charset (acentos viravam ?) e os erros de SQL passavam em silêncio. O Rui quer a conexão de produção.",
                "Crie $pdo com o DSN \"mysql:host=localhost;dbname=cafe;charset=utf8mb4\", $usuario e $senha, e um array de opções (nessa ordem): modo de erro por exceção e modo de busca padrão associativo.",
                PhpMix("$pdo = new PDO(\"mysql:host=localhost;dbname=cafe;charset=utf8mb4\", $usuario, $senha, [\n    @0::ATTR_ERRMODE => @0::ERRMODE_EXCEPTION,\n    @0::ATTR_DEFAULT_FETCH_MODE => @0::FETCH_ASSOC@1\n]);",
                    new[] { "PDO", "\\PDO" }, new[] { "", "," }),
                A("O 4º argumento do new PDO é um array [atributo => valor]. Os atributos são ATTR_ERRMODE e ATTR_DEFAULT_FETCH_MODE.", "new PDO(\"mysql:...;charset=utf8mb4\", $usuario, $senha, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);"),
                A("charset=utf8mb4", "UTF-8 completo (inclusive emojis) na conexão.", "PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION", "Erro de SQL vira exceção (não passa em silêncio).",
                  "PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC", "fetch/fetchAll devolvem arrays associativos por padrão."),
                "No PHP 8 o ERRMODE_EXCEPTION já é o padrão, mas deixe explícito. Considere também PDO::ATTR_EMULATE_PREPARES => false."));
            list.Add(C(H, 2, "cmd", "Deploy sem dev",
                "No servidor de produção, a pasta vendor/ trazia PHPUnit e Faker (superfície de ataque à toa) e o autoload fazia milhares de verificações de arquivo.",
                "Instale as dependências do projeto sem os pacotes de desenvolvimento e com o autoloader otimizado (classmap), usando as opções longas ou -o.",
                A("composer install --no-dev --optimize-autoloader", "composer install --optimize-autoloader --no-dev",
                  "composer install --no-dev -o", "composer install -o --no-dev"),
                A("É o composer install, com uma opção para pular o require-dev e outra para otimizar o autoload.", "composer install --no-___ --optimize-__________"),
                A("--no-dev", "Não instala os pacotes de require-dev.", "--optimize-autoloader", "Gera um classmap: o autoload acha as classes sem procurar arquivos."),
                "Em produção nunca rode composer update: ele pode trazer versões novas não testadas. install respeita o composer.lock."));
            list.Add(C(H, 2, "code", "Ordenação por lista branca",
                "?ordem=preco ordena a listagem, mas ORDER BY não aceita marcador ? (nome de coluna não é valor). O código concatenava $_GET direto no SQL: injeção.",
                "Guarde em $ordem o parâmetro ordem do GET ou \"nome\" (com ??); depois, se $ordem não estiver na lista [\"nome\", \"preco\"] (in_array estrito, com true), volte $ordem para \"nome\".",
                PhpMix("$ordem = $_GET[\"ordem\"] ?? \"nome\";\nif (!in_array($ordem, @0, true)) {\n    $ordem = \"nome\";\n}",
                    new[] { "[\"nome\", \"preco\"]", "[\"preco\", \"nome\"]", "array(\"nome\", \"preco\")" }),
                A("Primeiro o valor com padrão (??). Depois, se NÃO estiver na lista permitida (!in_array), troque pelo padrão.", "$ordem = $_GET[\"ordem\"] ?? \"nome\";\nif (!in_array($ordem, [\"nome\", \"preco\"], true)) {\n    $ordem = ...;\n}"),
                A("$_GET[\"ordem\"] ?? \"nome\"", "Padrão quando o parâmetro não vem.", "!in_array(..., true)", "Fora da lista permitida → recusa (comparação estrita).", "$ordem = \"nome\"", "Valor seguro: agora pode ir no ORDER BY."),
                "Lista branca (allowlist) é a defesa para identificadores: colunas, ASC/DESC e nomes de tabela nunca podem ser parâmetros."));
            list.Add(C(H, 2, "code", "Gerando token CSRF",
                "Um site malicioso conseguiu enviar pedidos em nome de clientes logados (CSRF). Cada formulário vai carregar um token secreto guardado na sessão.",
                "Guarde em $_SESSION[\"csrf_token\"] 32 bytes aleatórios criptograficamente seguros convertidos para hexadecimal (random_bytes dentro de bin2hex).",
                A("$_SESSION[\"csrf_token\"] = bin2hex(random_bytes(32));"),
                A("random_bytes(n) gera bytes seguros, mas binários; bin2hex os transforma em texto.", "$_SESSION[\"csrf_token\"] = bin2hex(random_bytes(__));"),
                A("random_bytes(32)", "32 bytes do gerador seguro do sistema.", "bin2hex(...)", "Vira 64 caracteres hexadecimais, prontos para o <input type=\"hidden\">."),
                "Nunca use rand(), mt_rand() ou uniqid() para segredos: são previsíveis. random_bytes e random_int são seguros."));
            list.Add(C(H, 2, "code", "Conferindo token CSRF",
                "No POST do pedido, o token do formulário (campo csrf_token) precisa bater com o da sessão. Comparar com == pode vazar informação pelo tempo de resposta.",
                "Escreva um if que entra quando o token NÃO confere: use !hash_equals com $_SESSION[\"csrf_token\"] primeiro e $_POST[\"csrf_token\"] ?? \"\" depois. Dentro: responda status 403 e encerre com exit.",
                PhpMix("if (!hash_equals($_SESSION[\"csrf_token\"], $_POST[\"csrf_token\"] ?? \"\")) {\n    http_response_code(403);\n    @0;\n}", exits),
                A("hash_equals(conhecido, recebido) compara em tempo constante. Negue com ! para entrar quando NÃO confere.", "if (!hash_equals($_SESSION[\"csrf_token\"], $_POST[\"csrf_token\"] ?? \"\")) {\n    http_response_code(403);\n    exit;\n}"),
                A("hash_equals(a, b)", "Compara strings sem vazar, pelo tempo, onde está a diferença.", "?? \"\"", "Campo ausente vira texto vazio (e falha na comparação).", "http_response_code(403)", "Proibido.", "exit", "Nada do pedido é processado."),
                "No Laravel, @csrf no formulário e o middleware VerifyCsrfToken fazem tudo isso sozinhos."));
            list.Add(C(H, 2, "code", "Model protegido",
                "Com Cliente::create($request->all()), alguém mandou is_admin=1 no formulário e virou administrador (mass assignment).",
                "Dentro do model Cliente, declare a propriedade protegida $fillable liberando só as colunas \"nome\", \"email\" e \"telefone\" (nessa ordem).",
                A("protected $fillable = [\"nome\", \"email\", \"telefone\"];", "protected $fillable = array(\"nome\", \"email\", \"telefone\");"),
                A("No Eloquent, a lista de colunas que podem ser preenchidas em massa é a propriedade $fillable.", "protected $fillable = [\"...\", \"...\", \"...\"];"),
                A("protected $fillable", "Colunas liberadas para create()/fill().", "[\"nome\", \"email\", \"telefone\"]", "is_admin fica de fora: é ignorado se vier no request."),
                "No controller, prefira Cliente::create($request->validated()) a $request->all()."));
            list.Add(C(H, 2, "code", "Erro sem vazar detalhes",
                "Quando o banco caía, a API respondia a mensagem do PDOException com usuário, host e até trechos do SQL. Isso ajuda o atacante.",
                "Escreva o bloco catch para PDOException como $e que, nessa ordem: registra $e->getMessage() no log do servidor com error_log, responde status 500 e mostra com echo o json_encode de [\"erro\" => \"erro interno\"].",
                PhpMix("catch (@0 $e) {\n    error_log($e->getMessage());\n    http_response_code(500);\n    echo json_encode([\"erro\" => \"erro interno\"]);\n}",
                    new[] { "PDOException", "\\PDOException" }),
                A("Detalhes vão para o log (error_log); o cliente recebe só uma mensagem genérica com status 500.", "catch (PDOException $e) {\n    error_log($e->getMessage());\n    http_response_code(500);\n    echo json_encode([...]);\n}"),
                A("error_log(...)", "Grava no log do servidor, não na resposta.", "http_response_code(500)", "Erro interno.", "\"erro interno\"", "Mensagem genérica: nada de detalhes técnicos."),
                "Em produção: display_errors=Off e log_errors=On no php.ini."));
            list.Add(C(H, 2, "cmd", "Cache de configuração",
                "Em produção, o Laravel lê e junta dezenas de arquivos de config/ a cada requisição. O checklist de deploy do Igor tem um passo para isso.",
                "Gere o cache de configuração do Laravel com o artisan.",
                A("php artisan config:cache"),
                A("Os comandos de configuração do artisan começam com config:.", "php artisan config:_____"),
                A("config:cache", "Junta toda a configuração num único arquivo PHP em bootstrap/cache."),
                "Depois do config:cache, env() fora dos arquivos de config/ devolve null — use config(\"app.nome\") no código. Para desfazer: config:clear."));
            list.Add(C(H, 2, "code", "Validando no Laravel",
                "O cadastro de clientes no Laravel aceita qualquer coisa. Nada de if espalhado: o Request valida e responde o erro sozinho.",
                "Guarde em $dados o retorno de $request->validate com as regras \"nome\" => \"required|max:100\" e \"email\" => \"required|email\" (nessa ordem).",
                PhpMix("$dados = $request->validate([\n    \"nome\" => @0,\n    \"email\" => @1@2\n]);",
                    new[] { "\"required|max:100\"", "[\"required\", \"max:100\"]" }, new[] { "\"required|email\"", "[\"required\", \"email\"]" }, new[] { "", "," }),
                A("validate recebe um array campo => regras; as regras são separadas por |.", "$dados = $request->validate([\n    \"nome\" => \"required|max:100\",\n    \"email\" => \"...\"\n]);"),
                A("$request->validate([...])", "Valida; se falhar, interrompe e responde com os erros.", "\"required|max:100\"", "Obrigatório e com no máximo 100 caracteres.", "$dados", "Só os campos validados."),
                "Na falha, o Laravel redireciona de volta (web) ou responde 422 em JSON (API), sem rodar o resto do método."));
            list.Add(C(H, 2, "code", "Hash desatualizado",
                "Os hashes antigos foram gerados com custo baixo. No login (senha já conferida com password_verify), o Rui quer atualizar o hash automaticamente.",
                "Escreva um if que, quando password_needs_rehash indicar que $usuario[\"senha_hash\"] precisa ser refeito para PASSWORD_DEFAULT, guarde em $novoHash o password_hash de $senha com PASSWORD_DEFAULT.",
                A("if (password_needs_rehash($usuario[\"senha_hash\"], PASSWORD_DEFAULT)) {\n    $novoHash = password_hash($senha, PASSWORD_DEFAULT);\n}"),
                A("password_needs_rehash(hash, algoritmo) devolve true se o hash usa algoritmo ou custo antigos.", "if (password_needs_rehash($usuario[\"senha_hash\"], PASSWORD_DEFAULT)) {\n    $novoHash = password_hash(...);\n}"),
                A("password_needs_rehash", "Compara o hash salvo com o algoritmo/custo atuais.", "password_hash($senha, PASSWORD_DEFAULT)", "Novo hash, com as configurações de hoje."),
                "Só no login você tem a senha em texto puro na mão: é a única hora de refazer o hash. Depois, grave $novoHash no banco (UPDATE com prepare)."));
            list.Add(C(H, 2, "code", "Consultas N+1",
                "A lista de 100 pedidos mostra o nome do cliente e fez 101 consultas ao banco: 1 para os pedidos e 1 por cliente. O Rui viu no log.",
                "Guarde em $pedidos todos os pedidos (model Pedido) já carregando de antemão o relacionamento \"cliente\" (eager loading), com with e get.",
                A("$pedidos = Pedido::with(\"cliente\")->get();", "$pedidos = Pedido::with([\"cliente\"])->get();"),
                A("O método que carrega relacionamentos antes de usar é with(\"relacionamento\").", "$pedidos = Pedido::with(\"...\")->get();"),
                A("with(\"cliente\")", "Busca todos os clientes numa consulta só (WHERE id IN (...)).", "->get()", "Executa e devolve a Collection."),
                "Com eager loading são só 2 consultas. Model::preventLazyLoading() acusa N+1 em desenvolvimento."));
            list.Add(C(H, 2, "code", "Dois erros, um catch",
                "finalizarPedido($pedido) pode lançar EstoqueInsuficienteException ou PagamentoRecusadoException. Nos dois casos, o cliente vê a mensagem; qualquer outro erro deve subir.",
                "Chame finalizarPedido($pedido) dentro de um try e capture as duas exceções num único catch (tipos separados por |) como $e, mostrando com echo $e->getMessage().",
                PhpMix("try {\n    finalizarPedido($pedido);\n} catch (@0 $e) {\n    echo $e->getMessage();\n}",
                    new[] { "EstoqueInsuficienteException | PagamentoRecusadoException", "PagamentoRecusadoException | EstoqueInsuficienteException" }),
                A("Desde o PHP 7.1, um catch aceita vários tipos separados por |.", "catch (EstoqueInsuficienteException | PagamentoRecusadoException $e) { ... }"),
                A("catch (A | B $e)", "Captura qualquer um dos dois tipos.", "$e->getMessage()", "Mensagem do erro que aconteceu."),
                "Capture só o que você sabe tratar. Erros inesperados devem subir até o handler global (e ir para o log)."));
            list.Add(C(H, 2, "code", "Status com enum",
                "O status do pedido era string solta: \"pago\", \"Pago\", \"PAGO\"... bugs por toda parte. O PHP 8.1 tem enums.",
                "Declare o enum StatusPedido com valores string (backed enum) e os casos Pendente = \"pendente\", Pago = \"pago\" e Entregue = \"entregue\" (nessa ordem).",
                A("enum StatusPedido: string {\n    case Pendente = \"pendente\";\n    case Pago = \"pago\";\n    case Entregue = \"entregue\";\n}"),
                A("Um enum com valores declara o tipo depois do nome (: string) e cada caso com case Nome = valor;", "enum StatusPedido: string {\n    case Pendente = \"pendente\";\n    ...\n}"),
                A("enum StatusPedido: string", "Enum \"apoiado\" por string: cada caso tem um valor.", "case Pago = \"pago\";", "StatusPedido::Pago->value vale \"pago\"."),
                "StatusPedido::from(\"pago\") converte o texto do banco (erro se inválido); tryFrom devolve null. No Eloquent: $casts = [\"status\" => StatusPedido::class]."));
            list.Add(C(H, 2, "cmd", "Auditoria de pacotes",
                "Saiu um alerta de vulnerabilidade numa biblioteca famosa. O Igor quer saber se alguma dependência instalada da api-pedidos tem falha de segurança conhecida.",
                "Verifique com o Composer se os pacotes instalados têm vulnerabilidades conhecidas.",
                A("composer audit"),
                A("O subcomando tem o nome de \"auditoria\" em inglês.", "composer _____"),
                A("composer audit", "Consulta o banco de avisos de segurança para as versões do composer.lock."),
                "Coloque composer audit no CI. Para ver as versões novas disponíveis: composer outdated."));
            list.Add(C(H, 2, "code", "Liberando o lock",
                "O processador da fila trava um lock antes de rodar. Quando processarFila() lançava exceção, o lock nunca era liberado e a fila parava para sempre.",
                "Depois de $lock->adquirir(), chame processarFila() dentro de um try e libere com $lock->liberar() num bloco finally (sem catch).",
                A("$lock->adquirir();\ntry {\n    processarFila();\n} finally {\n    $lock->liberar();\n}"),
                A("O bloco que roda SEMPRE, com ou sem exceção, é o finally.", "$lock->adquirir();\ntry {\n    processarFila();\n} finally {\n    ...\n}"),
                A("try { processarFila(); }", "Pode lançar exceção.", "finally { $lock->liberar(); }", "Roda sempre; a exceção continua subindo depois."),
                "finally roda com sucesso, com exceção e até com return dentro do try. Ideal para liberar recursos (locks, arquivos, conexões)."));
            list.Add(C(H, 2, "code", "Lista paginada no Eloquent",
                "/produtos devolvia os 5 mil produtos de uma vez e o app travava.",
                "Guarde em $produtos os produtos (model Produto) com a coluna ativo igual a true, ordenados por \"nome\" e paginados de 20 em 20 (where, orderBy e paginate, nessa ordem).",
                PhpMix("$produtos = Produto::where(\"ativo\", @0true)->orderBy(\"nome\"@1)->paginate(20);", new[] { "", "\"=\", " }, new[] { "", ", \"asc\"" }),
                A("Encadeie: where(...)->orderBy(...)->paginate(quantidade).", "$produtos = Produto::where(\"ativo\", true)->orderBy(\"nome\")->paginate(__);"),
                A("where(\"ativo\", true)", "Só os ativos.", "orderBy(\"nome\")", "Ordem alfabética.", "paginate(20)", "20 por página; lê ?page= da URL e conta o total."),
                "Em tabelas enormes, cursorPaginate evita o COUNT e o OFFSET alto. Crie índice nas colunas do where e do orderBy."));
            list.Add(C(H, 2, "code", "Corpo JSON da requisição",
                "O app Flutter envia o pedido por POST com Content-Type: application/json — e $_POST vem vazio! E JSON malformado passava em silêncio como null.",
                "Guarde em $dados o corpo bruto da requisição (lido de php://input com file_get_contents) decodificado com json_decode como array associativo, profundidade 512 e a flag que lança exceção em JSON inválido.",
                A("$dados = json_decode(file_get_contents(\"php://input\"), true, 512, JSON_THROW_ON_ERROR);",
                  "$corpo = file_get_contents(\"php://input\");\n$dados = json_decode($corpo, true, 512, JSON_THROW_ON_ERROR);"),
                A("O corpo bruto está no fluxo php://input. json_decode(texto, assoc, profundidade, flags).", "$dados = json_decode(file_get_contents(\"php://input\"), true, 512, JSON_THROW_____);"),
                A("file_get_contents(\"php://input\")", "Lê o corpo bruto da requisição.", "true, 512", "Arrays associativos; profundidade máxima padrão.", "JSON_THROW_ON_ERROR", "JSON inválido lança JsonException em vez de devolver null."),
                "Capture JsonException e responda 400. $_POST só é preenchido para formulários (x-www-form-urlencoded e multipart)."));
            list.Add(C(H, 2, "code", "Teste da regra do frete",
                "A função frete(float $total): float devolve 0.0 a partir de R$ 50 e 7.5 abaixo disso. O bug clássico mora na fronteira.",
                "Dentro de um teste PHPUnit, escreva duas asserções com $this->assertSame (valor esperado primeiro): frete(50.0) deve ser 0.0 e frete(49.99) deve ser 7.5.",
                PhpMix("@0assertSame(0.0, frete(50.0));\n@0assertSame(7.5, frete(49.99));", new[] { "$this->", "self::", "static::" }),
                A("assertSame(esperado, obtido) compara com ===. Teste os dois lados da fronteira.", "$this->assertSame(0.0, frete(50.0));\n$this->assertSame(7.5, frete(...));"),
                A("assertSame", "Confere valor E tipo (===).", "frete(50.0)", "Exatamente na fronteira: já é grátis.", "frete(49.99)", "Um centavo abaixo: paga 7.5."),
                "assertSame(0, 0.0) falha (int x float) — é isso que pega bugs de tipo. assertEquals seria mais permissivo."));
            list.Add(C(H, 2, "cmd", "Migration em produção",
                "No deploy automatizado, php artisan migrate parou esperando alguém digitar yes: em produção o Laravel pede confirmação.",
                "Rode as migrations do Laravel forçando a execução em produção, sem pergunta interativa.",
                A("php artisan migrate --force"),
                A("É o migrate de sempre, com uma opção que \"força\" a execução.", "php artisan migrate --_____"),
                A("migrate", "Aplica as migrations pendentes.", "--force", "Pula a confirmação do ambiente de produção."),
                "Antes de migrar em produção, tenha backup. Mudanças destrutivas (apagar coluna) devem ser feitas em etapas."));
            list.Add(C(H, 2, "code", "Redirecionar depois do POST",
                "Depois de criar um pedido, o F5 do cliente reenviava o formulário e duplicava a compra. Solução: o padrão Post/Redirect/Get.",
                "Redirecione para /pedidos/ seguido de $id com header (Location), passando true como segundo argumento e o status 303 como terceiro; depois encerre com exit.",
                PhpMix("header(@0, true, 303);\n@1;", new[] { "\"Location: /pedidos/\" . $id", "\"Location: /pedidos/$id\"", "\"Location: /pedidos/{$id}\"" }, exits),
                A("header(\"Location: url\", substituir, status). Depois de redirecionar, pare o script.", "header(\"Location: /pedidos/\" . $id, true, 303);\nexit;"),
                A("Location: /pedidos/...", "Para onde o navegador deve ir.", "303", "See Other: o navegador faz um GET na nova URL.", "exit", "Sem ele, o resto do script continua rodando."),
                "Com PRG, o F5 repete só o GET da página do pedido, nunca o POST. No Laravel: return redirect()->route(...)."));
            list.Add(C(H, 2, "code", "Blade sem XSS",
                "Na página de avaliações, alguém escreveu um comentário com <script> e ele executou. O template usava {!! $avaliacao->comentario !!}.",
                "Reescreva o parágrafo <p>...</p> mostrando $avaliacao->comentario escapado com a sintaxe padrão de saída do Blade.",
                A("<p>{{ $avaliacao->comentario }}</p>", "<p>{{ e($avaliacao->comentario) }}</p>"),
                A("No Blade, {!! !!} imprime HTML cru. A sintaxe com chaves duplas escapa.", "<p>{{ ... }}</p>"),
                A("{{ $avaliacao->comentario }}", "Passa por htmlspecialchars: <script> vira texto inofensivo.", "{!! ... !!}", "Sem escape: só para HTML que VOCÊ gerou e confia."),
                "Nunca use {!! !!} com conteúdo do usuário. Se precisar permitir formatação, use uma biblioteca de sanitização (ex.: HTML Purifier)."));
            list.Add(C(H, 2, "code", "Senha fora do código",
                "A senha do banco estava escrita no config.php — e o arquivo foi parar num repositório público. Agora ela vem da variável de ambiente DB_PASS.",
                "Em uma linha, guarde em $senha o valor de getenv(\"DB_PASS\"); se vier vazio ou false, lance uma RuntimeException com a mensagem \"DB_PASS não definida\", usando o operador ?: e throw como expressão.",
                PhpMix("$senha = getenv(\"DB_PASS\") ?: throw new @0RuntimeException(\"DB_PASS @1 definida\");", new[] { "", "\\" }, new[] { "não", "nao" }),
                A("getenv devolve false (não null) quando a variável não existe — por isso ?: e não ??. No PHP 8, throw pode ser usado como expressão.", "$senha = getenv(\"DB_PASS\") ?: throw new RuntimeException(\"...\");"),
                A("getenv(\"DB_PASS\")", "Lê a variável de ambiente (ou false).", "?:", "Se o da esquerda for \"falso\" (false, \"\"), usa o da direita.", "throw new RuntimeException(...)", "Falha já na inicialização, com mensagem clara."),
                "Falhar cedo é melhor que conectar com senha vazia. No Laravel, segredos ficam no .env (fora do git) e são lidos via config()."));
            list.Add(C(H, 2, "code", "Cabeçalhos de segurança",
                "O pentest pediu dois cabeçalhos HTTP em todas as respostas: impedir que o navegador \"adivinhe\" o tipo do arquivo e impedir que o site seja carregado dentro de iframes (clickjacking).",
                "Envie com header, nessa ordem: X-Content-Type-Options com o valor nosniff e X-Frame-Options com o valor DENY.",
                A("header(\"X-Content-Type-Options: nosniff\");\nheader(\"X-Frame-Options: DENY\");"),
                A("Cada cabeçalho é um header(\"Nome: valor\"); separado.", "header(\"X-Content-Type-Options: ...\");\nheader(\"X-Frame-Options: ...\");"),
                A("X-Content-Type-Options: nosniff", "O navegador respeita o Content-Type enviado (sem \"farejar\").", "X-Frame-Options: DENY", "Ninguém pode exibir a página num iframe."),
                "Complete com Content-Security-Policy (frame-ancestors substitui X-Frame-Options nos navegadores modernos) e Strict-Transport-Security."));
        }
    }

    static partial class Docs
    {
        static partial void DocsExtraPhp(List<DocEntry> all)
        {
            const string H = "PHP";
            all.Add(X(H, "Básico", "const / define  (constantes)", "Valores fixos com nome. Não usam $ e não podem ser alterados depois.",
                "const NOME = valor;\ndefine(\"NOME\", valor);",
                A("const", "em tempo de compilação (topo do arquivo ou dentro de classes)", "define()", "em tempo de execução (pode ficar dentro de um if)"),
                A("const LIMITE_ALUNOS = 40;", "constante inteira", "echo LIMITE_ALUNOS;", "usa sem $"),
                "Por convenção, nomes de constantes são MAIÚSCULOS com _ separando as palavras."));
            all.Add(X(H, "Básico", "Operadores: ++  --  +=  .=", "Atalhos para alterar o valor de uma variável.",
                "$x++;   $x--;\n$x += 5;   $x -= 5;   $x *= 2;\n$texto .= \"mais\";", null,
                A("$faltas++;", "soma 1", "$saldo -= 10;", "subtrai 10", "$frase .= \"!\";", "acrescenta ao fim do texto"),
                "$x++ devolve o valor antigo e depois soma; ++$x soma antes."));
            all.Add(X(H, "Básico", "if / elseif / else", "Executa um bloco só quando a condição é verdadeira.",
                "if (condicao) {\n    ...\n} elseif (outra) {\n    ...\n} else {\n    ...\n}",
                A("> < >= <=", "comparações", "=== / !==", "igual / diferente (valor E tipo)", "&& / || / !", "e / ou / não"),
                A("if ($nota >= 6) {\n    echo \"Aprovado\";\n}", "mostra só se a nota for 6 ou mais"),
                "Prefira === a ==: no PHP, == converte tipos antes de comparar."));
            all.Add(X(H, "Básico", "for / while", "for repete com um contador; while repete enquanto a condição for verdadeira.",
                "for (inicio; condicao; passo) { ... }\nwhile (condicao) { ... }", null,
                A("for ($n = 10; $n >= 0; $n--) {\n    echo $n;\n}", "contagem regressiva de 10 a 0",
                  "while ($tentativas < 3) {\n    $tentativas++;\n}", "repete até 3 tentativas"),
                "break sai do laço; continue pula para a próxima volta."));
            all.Add(X(H, "Básico", "Funções de string", "Funções nativas para tamanho, maiúsculas, limpeza e busca em textos.",
                "strlen($s)  strtoupper($s)  strtolower($s)  trim($s)\nstr_contains($s, $trecho)  str_starts_with($s, $inicio)  str_ends_with($s, $fim)",
                A("strlen / mb_strlen", "tamanho em bytes / em caracteres (UTF-8)", "strtoupper / strtolower", "maiúsculas / minúsculas (mb_ para acentos)",
                  "trim / ltrim / rtrim", "remove espaços das pontas", "str_contains", "contém o trecho? (PHP 8)", "str_replace(de, para, $s)", "troca trechos"),
                A("echo strlen($senha);", "quantos caracteres", "$turma = strtoupper($turma);", "padroniza em maiúsculas", "$ok = str_starts_with($telefone, \"+55\");", "começa com +55?"),
                "As funções de string devolvem um texto NOVO: guarde o resultado ($s = trim($s);)."));
            all.Add(X(H, "Básico", "implode / explode", "implode junta os itens de um array numa string; explode quebra uma string num array.",
                "implode(separador, $array)\nexplode(separador, $texto)", null,
                A("echo implode(\" | \", $materias);", "Matemática | História | Física", "$partes = explode(\"-\", \"2026-10-15\");", "[\"2026\", \"10\", \"15\"]"),
                "Nas duas funções o SEPARADOR vem primeiro. join() é apelido de implode()."));
            all.Add(X(H, "Básico", "round / number_format", "round arredonda números; number_format formata para exibição (casas decimais e separadores).",
                "round($numero, casas)\nnumber_format($numero, casas, sepDecimal, sepMilhar)",
                A("floor / ceil", "arredonda sempre para baixo / para cima"),
                A("echo round(7.456, 2);", "7.46", "echo number_format(98765.4, 2, \",\", \".\");", "98.765,40"),
                "number_format devolve STRING: use só para mostrar, nunca para continuar calculando."));
            all.Add(X(H, "Básico", "var_dump / print_r  (depuração)", "Mostram o conteúdo de variáveis. var_dump inclui tipos e tamanhos.",
                "var_dump($variavel);\nprint_r($array);", null,
                A("var_dump($boletim);", "array(2) { [\"nota\"]=> float(8.5) ... }", "print_r($boletim);", "Array ( [nota] => 8.5 ... )"),
                "Remova antes de publicar: em produção isso vaza dados. No Laravel: dd($x)."));
            all.Add(X(H, "Básico", "Funções: valor padrão e tipo nullable", "Parâmetros podem ter valor padrão (usado se o argumento não vier) e tipos que aceitam null (?tipo).",
                "function nome($param = padrao) { ... }\nfunction nome(?string $param): string { ... }",
                A("$x = \"padrão\"", "valor padrão", "?string", "string ou null (o mesmo que string|null)"),
                A("function despedida($quem = \"turma\") { return \"Tchau, \" . $quem; }", "despedida() → \"Tchau, turma\"",
                  "function sigla(?string $curso): string { return $curso ?? \"N/D\"; }", "trata o null com ??"),
                "Parâmetros com valor padrão vêm depois dos obrigatórios."));
            all.Add(X(H, "Arrays", "Acrescentar e ler: $a[] / $a[\"chave\"]", "$array[] = valor acrescenta no fim; $array[\"chave\"] lê ou grava pela chave.",
                "$lista[] = valor;\narray_push($lista, valor);\n$assoc[\"chave\"]", null,
                A("$presentes[] = \"Bia\";", "acrescenta Bia no fim", "echo $aluno[\"turma\"];", "lê a chave turma", "$aluno[\"turma\"] = \"3B\";", "grava/troca a chave turma"),
                "Ler uma chave que não existe gera aviso: use $aluno[\"turma\"] ?? \"sem turma\"."));
            all.Add(X(H, "Arrays", "array_sum / usort / <=>", "array_sum soma os valores. usort ordena com uma função de comparação; o operador <=> (nave espacial) devolve -1, 0 ou 1.",
                "array_sum($array)\nusort($array, fn($a, $b) => $a[...] <=> $b[...]);",
                A("sort / rsort", "ordena valores simples (crescente / decrescente)", "$a <=> $b", "crescente", "$b <=> $a", "decrescente"),
                A("$pontos = array_sum($placar);", "soma tudo", "usort($alunos, fn($x, $y) => $x[\"idade\"] <=> $y[\"idade\"]);", "ordena alunos por idade"),
                "usort altera o próprio array e devolve true."));
            all.Add(X(H, "Ferramentas", "php (linha de comando)", "O executável php mostra informações, verifica sintaxe e roda scripts.",
                "php -v\nphp -l arquivo.php\nphp arquivo.php",
                A("-v, --version", "versão instalada", "-l, --syntax-check", "só verifica a sintaxe (lint)", "-m", "lista as extensões", "--ini", "mostra o php.ini em uso", "-S host:porta", "servidor embutido"),
                A("php -l boletim.php", "No syntax errors detected in boletim.php", "php importar.php", "executa o script no terminal"), null));
            all.Add(X(H, "Ferramentas", "composer: require --dev / install --no-dev / audit", "Gerencia as dependências do projeto (composer.json e composer.lock).",
                "composer require PACOTE\ncomposer require --dev PACOTE\ncomposer install --no-dev --optimize-autoloader\ncomposer audit",
                A("--dev", "dependência só de desenvolvimento (require-dev)", "--no-dev", "não instala o require-dev (produção)", "-o, --optimize-autoloader", "gera classmap (autoload mais rápido)",
                  "audit", "procura vulnerabilidades conhecidas", "outdated", "lista pacotes com versão nova", "dump-autoload", "regera o autoload"),
                A("composer require --dev mockery/mockery", "pacote só para testes", "composer require monolog/monolog", "pacote de produção"),
                "Em produção use install (respeita o composer.lock), nunca update."));
            all.Add(X(H, "Laravel", "php artisan  (comandos do dia a dia)", "A CLI do Laravel: servidor, geradores, migrations, cache e testes.",
                "php artisan COMANDO [opções]",
                A("serve", "servidor de desenvolvimento (porta 8000)", "make:controller Nome", "gera um controller", "make:migration create_xxx_table", "gera uma migration",
                  "migrate --force", "migra em produção sem perguntar", "config:cache / config:clear", "cria / apaga o cache de configuração",
                  "test --filter=Nome", "roda só os testes que casam com o nome", "route:list", "lista as rotas"),
                A("php artisan make:controller TurmaController", "controller novo", "php artisan make:migration create_matriculas_table", "migration da tabela matriculas",
                  "php artisan serve --port=8080", "outra porta"),
                "Depois do config:cache, env() só funciona dentro dos arquivos de config/."));
            all.Add(X(H, "Laravel", "Rota com função anônima e view()", "Uma rota pode responder com uma closure em vez de um controller — bom para páginas estáticas.",
                "Route::get(\"/caminho\", function () {\n    return view(\"nome\");\n});",
                A("view(\"nome\")", "renderiza resources/views/nome.blade.php", "fn () => ...", "arrow function também serve", "Route::view(\"/x\", \"nome\")", "atalho para views estáticas"),
                A("Route::get(\"/contato\", function () {\n    return view(\"contato\");\n});", "página de contato"), null));
            all.Add(X(H, "Laravel", "Eloquent: where / first / with / paginate", "Consultas pelo model, encadeando métodos. Por baixo, o Eloquent usa prepared statements.",
                "Model::where(\"coluna\", $valor)->first();\nModel::with(\"relacao\")->get();\nModel::where(...)->orderBy(\"col\")->paginate(N);",
                A("first()", "primeiro resultado ou null", "firstOrFail()", "primeiro ou erro 404", "get()", "todos (Collection)", "find($id)", "pela chave primária",
                  "with(\"relacao\")", "eager loading: evita o problema N+1", "orderBy(\"col\", \"desc\")", "ordenação", "paginate(N)", "N por página (lê ?page=)"),
                A("$aluno = Aluno::where(\"matricula\", $mat)->first();", "um aluno pela matrícula", "$turmas = Turma::with(\"professor\")->get();", "turmas + professores em 2 consultas",
                  "$livros = Livro::where(\"disponivel\", true)->orderBy(\"titulo\")->paginate(15);", "15 livros por página"),
                "N+1: acessar $turma->professor dentro de um foreach sem with() faz uma consulta por item."));
            all.Add(X(H, "Laravel", "$fillable / $request->validate", "$fillable lista as colunas liberadas para preenchimento em massa; validate confere os dados do request antes de usar.",
                "protected $fillable = [\"col1\", \"col2\"];\n$dados = $request->validate([\"campo\" => \"regra1|regra2\"]);",
                A("required", "obrigatório", "email", "formato de e-mail", "max:N / min:N", "tamanho máximo / mínimo", "integer / numeric", "número", "unique:tabela", "não pode repetir no banco"),
                A("protected $fillable = [\"titulo\", \"autor\"];", "no model Livro",
                  "$dados = $request->validate([\"titulo\" => \"required|max:200\", \"ano\" => \"required|integer\"]);", "valida e devolve só esses campos"),
                "Na falha, o Laravel responde sozinho (redirect com erros, ou 422 em JSON)."));
            all.Add(X(H, "Laravel", "Blade: {{ }} e {!! !!}", "{{ }} mostra o valor ESCAPADO (seguro contra XSS); {!! !!} mostra HTML cru.",
                "{{ $variavel }}\n{!! $htmlConfiavel !!}", null,
                A("<h1>{{ $turma->nome }}</h1>", "escapado: seguro para dados do usuário", "@csrf", "campo oculto com o token CSRF (em formulários)"),
                "Use {!! !!} só para HTML gerado e confiado por você."));
            all.Add(X(H, "Orientação a objetos", "new, -> e $this", "new cria um objeto; -> acessa propriedades e métodos; dentro da classe, $this é o próprio objeto.",
                "$obj = new Classe(args);\n$obj->propriedade\n$obj->metodo()\n$this->propriedade   (dentro da classe)",
                A("nome: valor", "argumento nomeado (PHP 8): new Livro(titulo: \"Dom Casmurro\")"),
                A("$livro = new Livro(\"Dom Casmurro\", 1899);", "cria o objeto", "echo $livro->titulo;", "lê a propriedade",
                  "public function resumo(): string { return $this->titulo . \" (\" . $this->ano . \")\"; }", "método que usa $this"),
                "O ponto (.) concatena strings; para objetos, sempre ->."));
            all.Add(X(H, "Orientação a objetos", "Exceções: throw / try / catch / finally", "throw lança um erro; try/catch captura; finally roda sempre.",
                "throw new TipoException(\"mensagem\");\ntry { ... } catch (TipoA | TipoB $e) { ... } finally { ... }",
                A("InvalidArgumentException", "argumento inválido", "RuntimeException", "erro em tempo de execução", "$e->getMessage()", "a mensagem",
                  "catch (A | B $e)", "vários tipos num catch", "finally", "roda com ou sem exceção", "?: throw ...", "throw como expressão (PHP 8)", "error_log($msg)", "grava no log do servidor"),
                A("if ($idade < 0) {\n    throw new InvalidArgumentException(\"Idade negativa\");\n}", "lança",
                  "try {\n    matricular($aluno);\n} catch (TurmaCheiaException $e) {\n    echo $e->getMessage();\n}", "captura um tipo específico",
                  "$arq = fopen(\"notas.csv\", \"r\");\ntry {\n    importar($arq);\n} finally {\n    fclose($arq);\n}", "fecha o arquivo sempre"),
                "Exceções personalizadas: class TurmaCheiaException extends RuntimeException {}"));
            all.Add(X(H, "Orientação a objetos", "enum  (PHP 8.1)", "Um tipo com um conjunto fechado de valores. Enums \"apoiados\" (backed) têm um valor string ou int em cada caso.",
                "enum Nome: string {\n    case Caso = \"valor\";\n}",
                A("Nome::Caso", "um caso", "Nome::Caso->value", "o valor (\"valor\")", "Nome::from(\"valor\")", "caso pelo valor (erro se não existir)", "Nome::tryFrom(\"valor\")", "caso ou null"),
                A("enum Turno: string {\n    case Manha = \"manha\";\n    case Noite = \"noite\";\n}", "dois turnos", "$t = Turno::from($linha[\"turno\"]);", "converte o texto do banco"), null));
            all.Add(X(H, "Web", "filter_input", "Lê um valor de GET/POST/COOKIE já validando, sem tocar nas superglobais.",
                "filter_input(INPUT_GET | INPUT_POST, \"campo\", FILTRO)",
                A("INPUT_GET / INPUT_POST", "origem do dado", "FILTER_VALIDATE_INT", "inteiro (ou false)", "FILTER_VALIDATE_EMAIL", "e-mail (ou false)", "null", "resultado quando o campo não veio"),
                A("$pagina = filter_input(INPUT_GET, \"pagina\", FILTER_VALIDATE_INT);", "?pagina=3 → 3; ?pagina=x → false"), null));
            all.Add(X(H, "Web", "Sessão: contador e logout", "Ler/alterar valores da sessão e encerrá-la de verdade.",
                "session_start();\n$_SESSION[\"k\"] = ($_SESSION[\"k\"] ?? 0) + 1;\n$_SESSION = [];\nsession_destroy();",
                A("session_destroy()", "apaga a sessão no servidor", "$_SESSION = []", "limpa os dados da requisição atual"),
                A("$_SESSION[\"cliques\"] = ($_SESSION[\"cliques\"] ?? 0) + 1;", "contador (repare nos parênteses)"),
                "?? tem precedência menor que +: $x ?? 0 + 1 é o mesmo que $x ?? (0 + 1)."));
            all.Add(X(H, "Web", "JSON: flags, php://input e erros", "Opções de json_encode/json_decode e como ler um corpo JSON enviado por POST.",
                "json_encode($dados, FLAG | FLAG)\njson_decode(file_get_contents(\"php://input\"), true, 512, JSON_THROW_ON_ERROR)",
                A("JSON_PRETTY_PRINT", "indentado", "JSON_UNESCAPED_UNICODE", "acentos sem \\u00..", "JSON_UNESCAPED_SLASHES", "não escapa /",
                  "JSON_THROW_ON_ERROR", "JSON inválido lança JsonException", "php://input", "corpo bruto da requisição"),
                A("echo json_encode($boletim, JSON_PRETTY_PRINT);", "JSON legível", "$entrada = json_decode(file_get_contents(\"php://input\"), true);", "lê o JSON enviado pelo app"),
                "$_POST só vem preenchido em formulários; JSON chega pelo php://input."));
            all.Add(X(H, "Web", "header: redirecionar e cabeçalhos de segurança", "header() envia cabeçalhos HTTP: redirecionamento (Location) e proteções do navegador.",
                "header(\"Location: /url\", true, 303);\nexit;\nheader(\"Nome-Do-Cabecalho: valor\");",
                A("303", "See Other: redireciona com GET (padrão Post/Redirect/Get)", "X-Content-Type-Options: nosniff", "não \"adivinha\" o tipo do arquivo",
                  "X-Frame-Options: DENY | SAMEORIGIN", "bloqueia iframes (clickjacking)", "Content-Security-Policy", "de onde scripts/estilos podem vir"),
                A("header(\"Location: /matriculas/\" . $codigo, true, 303);\nexit;", "volta para a matrícula criada", "header(\"Referrer-Policy: no-referrer\");", "outro cabeçalho de segurança"),
                "Sempre exit depois de Location, e nenhum echo antes de header()."));
            all.Add(X(H, "Banco e segurança", "PDO: opções da conexão, query e LIKE", "Como abrir a conexão de produção, executar SQL fixo e buscar com LIKE sem SQL Injection.",
                "new PDO($dsn, $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, ...]);\n$pdo->query(\"SQL FIXO\")->fetchColumn();\n$stmt->execute([\"%\" . $termo . \"%\"]);",
                A("charset=utf8mb4 (no DSN)", "acentos e emojis corretos", "PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC", "arrays associativos por padrão",
                  "query()", "só para SQL sem dados externos", "fetch() / fetchColumn()", "uma linha / um valor"),
                A("$db = new PDO(\"mysql:host=db;dbname=escola;charset=utf8mb4\", $u, $p, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);", "conexão",
                  "$q = $db->prepare(\"SELECT * FROM alunos WHERE nome LIKE ?\");\n$q->execute([\"%\" . $termo . \"%\"]);", "o % vai no valor, não no SQL"),
                "ORDER BY coluna não aceita marcador: valide o nome com uma lista branca (in_array(..., true))."));
            all.Add(X(H, "Banco e segurança", "Tokens: random_bytes / bin2hex / hash_equals", "Gerar segredos imprevisíveis e compará-los com segurança (CSRF, tokens de API, links de recuperação).",
                "$token = bin2hex(random_bytes(32));\nhash_equals($esperado, $recebido)",
                A("random_bytes(n)", "n bytes criptograficamente seguros", "random_int(min, max)", "inteiro seguro", "hash_equals", "comparação em tempo constante"),
                A("$_SESSION[\"token_matricula\"] = bin2hex(random_bytes(16));", "token de 32 caracteres hex", "if (hash_equals($salvo, $_GET[\"t\"] ?? \"\")) { ... }", "confere o token"),
                "rand(), mt_rand() e uniqid() são previsíveis: nunca use para segredos."));
            all.Add(X(H, "Banco e segurança", "password_needs_rehash", "Diz se um hash salvo foi gerado com algoritmo ou custo antigos e deve ser refeito.",
                "if (password_needs_rehash($hash, PASSWORD_DEFAULT)) { ... }", null,
                A("if (password_needs_rehash($prof[\"hash\"], PASSWORD_DEFAULT)) {\n    $h = password_hash($pin, PASSWORD_DEFAULT);\n}", "refaz o hash no login"),
                "Só dá para refazer quando você tem a senha em texto puro: logo depois de um password_verify bem-sucedido."));
            all.Add(X(H, "Banco e segurança", "getenv  (segredos no ambiente)", "Lê variáveis de ambiente — onde senhas e chaves devem ficar, fora do código.",
                "getenv(\"NOME\")   (devolve false se não existir)\n$x = getenv(\"NOME\") ?: throw new RuntimeException(\"...\");",
                A("?:", "usa o da direita se o da esquerda for falso (false, \"\", 0)", "??", "só trata null/inexistente — não serve para o false do getenv"),
                A("$chave = getenv(\"API_KEY\") ?: throw new RuntimeException(\"API_KEY ausente\");", "falha cedo se faltar"),
                "No Laravel: variáveis no .env (fora do git) e leitura via config()."));
            all.Add(X(H, "Testes", "PHPUnit: assertSame e --filter", "Asserções conferem o resultado do código. assertSame compara valor E tipo (===).",
                "$this->assertSame(esperado, obtido);\nphp artisan test --filter=NomeDoTeste\nvendor/bin/phpunit",
                A("assertSame", "=== (tipo e valor)", "assertEquals", "== (mais permissivo)", "assertTrue / assertFalse", "booleanos", "assertCount(n, $array)", "quantidade de itens"),
                A("$this->assertSame(10.0, desconto(100.0));", "esperado primeiro, obtido depois", "php artisan test --filter=BoletimTest", "roda só esse teste"),
                "Teste os valores de fronteira (exatamente no limite e logo abaixo)."));
        }
